#include "sleela_registry_v3.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>
static void read_all(const char*p,char*o,size_t c){FILE*f=fopen(p,"rb");size_t n;assert(f);n=fread(o,1,c-1,f);o[n]=0;fclose(f);}
static void test_ids_and_capacity(void){char a[33],b[33];slr3_registry*r;slr3_record x,y;assert(slr3_id_from_seed("same-seed",a)==SLR3_OK);assert(slr3_id_from_seed("same-seed",b)==SLR3_OK&&!strcmp(a,b)&&strlen(a)==32);r=slr3_registry_create("dddddddddddddddddddddddddddddddd",1);assert(r);slr3_record_init(&x,"66666666666666666666666666666666","sleela.test","entry","One");slr3_record_init(&y,"77777777777777777777777777777777","sleela.test","entry","Two");assert(slr3_registry_add(r,&x)==SLR3_OK);assert(slr3_registry_add(r,&y)==SLR3_LIMIT);slr3_registry_destroy(r);}
static void test_records(void){const char*rid="aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",*id1="11111111111111111111111111111111",*id2="22222222222222222222222222222222";slr3_registry*r=slr3_registry_create(rid,32),*l=slr3_registry_create(rid,32);slr3_record a,b;char before[8192],after[8192],report[8192];const slr3_record*g;assert(r&&l);slr3_record_init(&a,id1,"sleela.runtime","service","Runtime Core");assert(slr3_registry_add(r,&a)==SLR3_OK);slr3_record_init(&b,id2,"sleela.package","package","Compiler Package");assert(slr3_registry_add(r,&b)==SLR3_OK);assert(slr3_registry_add_alias(r,id1,"runtime")==SLR3_OK);assert(slr3_registry_identify(r,"sleela.runtime","runtime")==slr3_registry_get(r,id1));assert(slr3_registry_add_alias(r,id1,"runtime")==SLR3_EXISTS);assert(slr3_registry_relate(r,id1,"depends_on",id2)==SLR3_OK);g=slr3_registry_get(r,id1);assert(g&&g->revision==3);assert(slr3_registry_rename(r,id1,"Renamed Runtime",g->revision)==SLR3_OK);g=slr3_registry_get(r,id1);assert(g&&!strcmp(g->id,id1)&&g->revision==4);assert(slr3_registry_rename(r,id1,"stale write",2)==SLR3_CONFLICT);assert(slr3_registry_transition(r,id1,"available",4)==SLR3_BAD_TRANSITION);assert(slr3_registry_transition(r,id1,"discovered",4)==SLR3_OK);g=slr3_registry_get(r,id1);assert(slr3_registry_transition(r,id1,"registered",g->revision)==SLR3_OK);assert(slr3_registry_save_v2(r,"registry-v3-test-a.sleelareg")==SLR3_OK);assert(slr3_registry_save_v2(r,"registry-v3-test-b.sleelareg")==SLR3_OK);read_all("registry-v3-test-a.sleelareg",before,sizeof before);read_all("registry-v3-test-b.sleelareg",after,sizeof after);assert(!strcmp(before,after));assert(slr3_registry_load_v2(l,"registry-v3-test-a.sleelareg")==SLR3_OK);assert(slr3_registry_count(l)==2);g=slr3_registry_get(l,id1);assert(g&&!strcmp(g->name,"Renamed Runtime")&&g->relationship_count==1&&g->alias_count==1);assert(slr3_registry_review(l,report,sizeof report)==SLR3_OK);assert(strstr(report,"Renamed Runtime"));{FILE*f=fopen("registry-v3-malformed.sleelareg","wb");assert(f);fputs("SLREG 2\nregistry=aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\nrecord\nid=bad\nend\n",f);fclose(f);assert(slr3_registry_load_v2(l,"registry-v3-malformed.sleelareg")==SLR3_MALFORMED);assert(slr3_registry_count(l)==2);remove("registry-v3-malformed.sleelareg");}slr3_registry_destroy(r);slr3_registry_destroy(l);remove("registry-v3-test-a.sleelareg");remove("registry-v3-test-b.sleelareg");}
static void test_modium(void){const char*rid="bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb",*id="33333333333333333333333333333333";slr3_registry*r=slr3_registry_create(rid,8);const slr3_record*x;uint64_t rev;assert(r);assert(slr3_modium_region_register(r,id,"VM backup region","file-backed","/safe/test/modium",SLR3_MIN_REGION_BYTES,"test-owner","1.0","")==SLR3_OK);x=slr3_registry_get(r,id);assert(x&&!strcmp(x->state,"registered")&&!strcmp(x->integrity_status,"unverified"));rev=x->revision;assert(slr3_registry_transition(r,id,"verified",rev)==SLR3_INTEGRITY);assert(slr3_registry_set_integrity(r,id,"intact",rev)==SLR3_OK);x=slr3_registry_get(r,id);rev=x->revision;assert(slr3_registry_transition(r,id,"verified",rev)==SLR3_OK);x=slr3_registry_get(r,id);assert(slr3_registry_transition(r,id,"available",x->revision)==SLR3_OK);assert(slr3_modium_region_register(r,"44444444444444444444444444444444","too small","file-backed","/tmp/no",SLR3_MIN_REGION_BYTES-1,"test","1.0","")==SLR3_INVALID);assert(slr3_modium_region_register(r,"55555555555555555555555555555555","USB","removable-volume","/media/usb",SLR3_MIN_REGION_BYTES,"test","1.0","")==SLR3_INVALID);slr3_registry_destroy(r);}
static void test_v1_migration(void){const char*rid="cccccccccccccccccccccccccccccccc";FILE*f=fopen("registry-v1-fixture.sleelareg","wb");slr3_registry*r=slr3_registry_create(rid,32);char ks[33],ka[33],id[33];const slr3_record*x;char report[8192];assert(f&&r);fputs("SLREG 1\n[Settings]\n= i memoryLimitMiB 2048\n= s verbosity normal mode\n[Artifacts/registry-core]\n@ sleela_registry.c | 2026-11-05T00:00:00Z | MEARVK LLC | 1.0.0 | 1dea0005ec0de001 | 0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef | 0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef\n",f);fclose(f);assert(slr3_id_from_seed("legacy-key|Settings",ks)==SLR3_OK);assert(slr3_id_from_seed("legacy-key|Artifacts/registry-core",ka)==SLR3_OK);assert(slr3_registry_migrate_v1("registry-v1-fixture.sleelareg","registry-v2-fixture.sleelareg",rid,32)==SLR3_OK);assert(slr3_registry_load_v2(r,"registry-v2-fixture.sleelareg")==SLR3_OK);assert(slr3_registry_count(r)==5);assert(slr3_registry_get(r,ks)&&slr3_registry_get(r,ka));assert(slr3_id_from_seed("legacy-value|Settings|memoryLimitMiB",id)==SLR3_OK);x=slr3_registry_get(r,id);assert(x&&!strcmp(x->payload_kind,"int")&&!strcmp(x->payload,"2048")&&x->relationship_count==1);assert(slr3_id_from_seed("legacy-value|Settings|verbosity",id)==SLR3_OK);x=slr3_registry_get(r,id);assert(x&&!strcmp(x->payload_kind,"string")&&!strcmp(x->payload,"normal mode"));assert(slr3_id_from_seed("legacy-provenance|Artifacts/registry-core",id)==SLR3_OK);x=slr3_registry_get(r,id);assert(x&&!strcmp(x->provenance_name,"sleela_registry.c")&&!strcmp(x->provenance_author,"MEARVK LLC")&&!strcmp(x->provenance_hex_id,"1dea0005ec0de001"));assert(slr3_registry_review(r,report,sizeof report)==SLR3_OK);assert(strstr(report,"Settings")&&strstr(report,"memoryLimitMiB"));slr3_registry_destroy(r);remove("registry-v1-fixture.sleelareg");remove("registry-v2-fixture.sleelareg");}
int main(void){test_ids_and_capacity();test_records();test_modium();test_v1_migration();puts("SLeeLa Registry 3.0 record tests: PASS");return 0;}
